import { useCallback, useEffect, useState } from "react";
import { RadioTower } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import { KillPort, ListPorts } from "../../wailsjs/go/controllers/System";
import { useDialogs } from "./dialogs/DialogProvider";
import { useT } from "../lib/i18n";

export type PortRow = {
  port: number;
  addr: string;
  pid: number;
  process: string;
};

// The ports panel: who listens where, and the one carefully fenced action —
// freeing a port, restricted to binaries this environment installed.
export default function PortsModal({ onClose }: { onClose: () => void }) {
  const t = useT();
  const dialogs = useDialogs();
  const [rows, setRows] = useState<PortRow[]>([]);

  const refresh = useCallback(() => {
    ListPorts().then((list: PortRow[]) => setRows(list ?? [])).catch(() => { /* pre-startup */ });
  }, []);

  useEffect(() => {
    refresh();
    const timer = window.setInterval(refresh, 3000);
    return () => window.clearInterval(timer);
  }, [refresh]);

  const free = async (row: PortRow) => {
    const yes = await dialogs.confirm({
      title: t("ports.killConfirmTitle", { port: String(row.port) }),
      message: `${t("ports.killConfirmBody")}\n\nPID ${row.pid} · ${row.process || "?"} · :${row.port}`,
      danger: true,
    });
    if (!yes) return;
    try {
      await KillPort(row.port);
    } catch (error) {
      await dialogs.alert({ title: t("ports.title"), message: String(error) });
    }
    refresh();
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        onClick={(event) => event.stopPropagation()}
        className="modal-card flex max-h-[70vh] w-[560px] max-w-[92vw] flex-col p-4"
      >
        <h2 className="mb-3 flex items-center gap-2 text-sm font-semibold text-white/90">
          <RadioTower className="h-4 w-4 text-accent2" /> {t("ports.title")}
        </h2>
        <div className="flex-1 overflow-auto">
          {rows.length === 0 ? (
            <p className="py-8 text-center text-xs text-white/45">{t("ports.empty")}</p>
          ) : (
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="text-white/40">
                  <th className="px-2 py-1.5 font-medium">Port</th>
                  <th className="px-2 py-1.5 font-medium">Address</th>
                  <th className="px-2 py-1.5 font-medium">PID</th>
                  <th className="px-2 py-1.5 font-medium">Process</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {rows.map((row) => (
                  <tr key={`${row.port}-${row.pid}`} className="border-t border-white/5 text-white/75">
                    <td className="px-2 py-1.5 font-mono">{row.port}</td>
                    <td className="px-2 py-1.5 font-mono text-white/50">{row.addr}</td>
                    <td className="px-2 py-1.5 font-mono text-white/50">{row.pid}</td>
                    <td className="px-2 py-1.5">{row.process || "—"}</td>
                    <td className="px-2 py-1.5 text-right">
                      <button
                        type="button"
                        onClick={() => void free(row)}
                        className="rounded border border-red-400/30 bg-red-500/10 px-2 py-0.5 text-[10px] text-red-300 hover:bg-red-500/20"
                      >
                        {t("ports.kill")}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
        <footer className="mt-3 flex justify-end">
          <button
            type="button"
            onClick={onClose}
            className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/75 hover:bg-white/10"
          >
            {t("ports.close")}
          </button>
        </footer>
      </div>
    </div>
  );
}
